from threading import Lock

def hashkey(args, kwargs):
    return hashlib.md5(functools.repr_(args) + functools.repr_(kwargs)).hexdigest()

def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if lock:
                lock.acquire()
                try:
                    result = cache.get(key(args, kwargs))
                    if result is None:
                        result = func(*args, **kwargs)
                        cache[key(args, kwargs)] = result
                finally:
                    lock.release()
            else:
                result = cache.get(key(args, kwargs))
                if result is None:
                    result = func(*args, **kwargs)
                    cache[key(args, kwargs)] = result
            return result
        return wrapper
    return decorator

import time
from functools import lru_cache

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def wrapper(func):
        cached_func = lru_cache(maxsize=maxsize, typed=typed)(func)
        cache_info = cached_func.cache_info

        def new_func(*args, **kwargs):
            current_time = timer()
            for key in list(cached_func.cache):
                if current_time - cached_func.cache_info()[2] >= ttl:
                    del cached_func.cache[key]
            return cached_func(*args, **kwargs)

        new_func.cache_info = lambda: cache_info
        return new_func
    return wrapper

class OrderedDict(dict):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._keys = []

    def __setitem__(self, key, value):
        if key not in self:
            self._keys.append(key)
        super().__setitem__(key, value)

    def __delitem__(self, key):
        super().__delitem__(key)
        self._keys.remove(key)

    def popitem(self):
        """Remove and return the `(key, value)` pair first inserted."""
        if not self:
            raise KeyError("popitem(): dictionary is empty")
        key = self._keys[0]
        value = super().__getitem__(key)
        self.__delitem__(key)
        return key, value

