def _legacy_mergeOrderings(orderings: List[List[str]]) -> List[str]:
    merged = []
    processed = set()
    for ordering in orderings:
        for item in ordering:
            if item not in processed and all(item in merged_suffix for merged_suffix in merged):
                merged.append(item)
                processed.add(item)
                break
    return merged + sum((o[len(merged):] for o in orderings), start=[])

