class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages

def _validate_labels(labels: Dict[str, Any]) -> None:
    key_regex = re.compile(r'^[a-zA-Z0-9-._~]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9-._~]+$')
    errors = []

    for key, value in labels.items():
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, str):
                    errors.append({repr(v): 'expected string or bytes-like object'})
                elif not value_regex.match(v):
                    errors.append({repr(v): 'Label value does not match the regex'})
        else:
            if not isinstance(value, str):
                errors.append({repr(key): 'expected string or bytes-like object'})
            elif not key_regex.match(key):
                errors.append({repr(key): 'Label key does not match the regex'})
            elif not value_regex.match(value):
                errors.append({repr(value): 'Label value does not match the regex'})

    if errors:
        raise ValidationError(errors)

