def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    import copy

    # Create a copy of the manifest_dict to avoid modifying the original input
    observer_schema = copy.deepcopy(manifest_dict)

    # Replace all non-list and non-dict values by None
    for key, value in observer_schema.items():
        if not isinstance(value, (dict, list)):
            observer_schema[key] = None

    # If it's the first level dictionary, copy values of identifying fields from the manifest
    if first_level:
        identifying_fields = ['apiVersion', 'kind', 'metadata', 'spec', 'status']
        for field in identifying_fields:
            if field in manifest_dict:
                observer_schema[field] = manifest_dict[field]

    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being updated.
        observer_schema (list): partial ``observer_schema``.
        response (list): partial response from the Kubernetes API.

    This function iterates through all observed fields and initializes their value
    in ``last_applied_manifest`` if they are not yet present.

    """
    for item in observer_schema:
        if isinstance(item, list):
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest, item, response
            )
        elif isinstance(item, dict):
            key = list(item.keys())[0]
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], item[key], response
            )
        else:
            last_applied_manifest[item] = None

