    IN_STYLE_ORDINAL = 'ordinal'

class OutStyleConverter:
    def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
    ) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        in_style = SQLParams.IN_STYLE_NAMED  # Example assumption

        if in_style == SQLParams.IN_STYLE_NAMED:
            out_params = {f'out_{key}': value for key, value in params.items()}
        elif in_style == SQLParams.IN_STYLE_ORDINAL:
            out_params = [None] * len(params)
            for i, value in enumerate(params):
                out_params[i] = f'out_{i+1}'
        else:
            raise ValueError("Unsupported in-style parameter style")

        # Replace placeholders in SQL query
        if in_style == SQLParams.IN_STYLE_NAMED:
            formatted_sql = sql.replace('?', '{?}')
        else:
            formatted_sql = sql.replace('?', '?')

        return formatted_sql, out_params

