import re

class InventoryValidator:
    def __init__(self, spec_version="1.0"):
        self.spec_version = spec_version

    def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if extract_spec_version:
            spec_version = self.extract_spec_version(inventory)
        else:
            spec_version = self.spec_version

        # Perform validation based on the extracted or default specification version
        if spec_version == "1.0":
            self.validate_version_1_0(inventory)
        else:
            raise ValueError(f"Unsupported specification version: {spec_version}")

    def extract_spec_version(self, inventory):
        """Extract specification version from the inventory type value."""
        type_value = inventory.get("type")
        if not type_value:
            return self.spec_version

        # Assuming type value is in the format ".spec-<version>"
        match = re.match(r'^\.spec-(\d+\.\d+)$', type_value)
        if match:
            return match.group(1)
        else:
            return None

    def validate_version_1_0(self, inventory):
        """Validate inventory based on specification version 1.0."""
        required_fields = {"item_id", "quantity", "price"}
        for field in required_fields:
            if field not in inventory:
                raise ValueError(f"Missing required field: {field}")

