def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Ensure fixity contains the required keys
    required_keys = {'files', 'algorithm', 'digest'}
    if not required_keys.issubset(fixity):
        raise ValueError("Fixity block must contain 'files', 'algorithm', and 'digest' keys")

    # Ensure all files in fixity are in the manifest
    fixity_files = fixity.get('files', [])
    for file in fixity_files:
        if file not in manifest_files:
            raise ValueError(f"File '{file}' in fixity block not found in manifest files")

    # Ensure algorithm is a string
    if not isinstance(fixity.get('algorithm', ''), str):
        raise ValueError("Fixity algorithm must be a string")

    # Ensure digest is a string
    if not isinstance(fixity.get('digest', ''), str):
        raise ValueError("Fixity digest must be a string")

    return True

