def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.load_inventory('root')
    content_digests = set()

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory')
        if not os.path.exists(inventory_path):
            raise ValueError(f"Invariant violated, version '{version_dir}' does not have an inventory.")

        inventory = self.load_inventory(version_dir)
        for file_path, file_digest in inventory.items():
            if file_path not in root_inventory:
                content_digests.add(file_digest)

        for file_path, root_digest in root_inventory.items():
            if file_path in inventory and inventory[file_path] != root_digest:
                content_digests.add(root_digest)

    return content_digests

def load_inventory(self, version_dir):
    """Load the inventory for the given version directory."""
    inventory_path = os.path.join(version_dir, 'inventory')
    if not os.path.exists(inventory_path):
        return {}

    with open(inventory_path, 'r') as f:
        inventory = {}
        for line in f:
            path, digest = line.strip().split()
            inventory[path] = digest
        return inventory

