def load_configurations(config_filenames: List[str], overrides: Optional[Dict[str, str]] = None, resolve_env: bool = True) -> Tuple[Dict[str, dict], List[logging.LogRecord]]:
    config_records = {}
    parse_errors = []
    logger = logging.getLogger(__name__)

    for config_filename in config_filenames:
        parser = ConfigParser()
        try:
            parser.read(config_filename)
        except Exception as e:
            log_record = logging.LogRecord(name=logger.name, level=logging.ERROR, pathname=config_filename, lineno=0, msg=str(e), args=(), exc_info=None)
            parse_errors.append(log_record)
            continue

        config_record = parser._sections.copy()
        if overrides:
            for key, value in overrides.items():
                if '.' in key:
                    section, option = key.split('.', 1)
                else:
                    section, option = None, key
                if section in config_record:
                    config_record[section][option] = value

        if resolve_env:
            for section, options in config_record.items():
                for option, value in options.items():
                    if value.startswith('${') and value.endswith('}'):
                        env_var = value[2:-1]
                        if env_var in os.environ:
                            config_record[section][option] = os.environ[env_var]

        config_records[config_filename] = config_record

    return config_records, parse_errors

