        if other is None:
            return self.scale
        else:
            if self.scale is None or self.scale == 0:
                raise ValueError("Rescaling with unknown or zero scale is not allowed")
            for field, values in self.fields.items():
                for i, value in enumerate(values):
                    self.fields[field][i] = value * other / self.scale
            self.scale = other

