def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) != len(getattr(hist, "_dims", (1,))):
        raise ValueError("field_names must have the same number of elements as the dimension of the histogram")

    if scale is True:
        scale = hist.scale

    points = []
    for bin_ in hist:
        value = make_value(bin_)
        if not isinstance(value, (list, tuple)):
            value = (value,)

        if len(value) != len(field_names):
            raise ValueError("The number of values in make_value output must match the number of field_names")

        x = bin_.bin_edges[0] if get_coordinate == "left" else bin_.bin_edges[-1] if get_coordinate == "right" else sum(bin_.bin_edges) / 2

        points.append((x, *value))

