import zope.interface

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"Candidate does not claim to provide {iface}")

    candidate_methods = set(dir(candidate))
    required_methods = set(iface.names()) - {None}
    missing_methods = required_methods - candidate_methods
    if missing_methods:
        raise zope.interface.Invalid(f"Candidate is missing methods: {missing_methods}")

    errors = []
    for method in required_methods:
        candidate_method = getattr(candidate, method)
        interface_method = getattr(iface, method)
        if not callable(candidate_method):
            errors.append(f"{method} is not a callable method")
        if not zope.interface.signature(candidate_method) == zope.interface.signature(interface_method):
            errors.append(f"{method} has incorrect signature")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

