        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        required_fields = {'field1', 'field2', 'field3'}  # Example required fields
        loaded_data = {}
        if yaml_file:
            try:
                with open(yaml_file, 'r') as file:
                    loaded_data = yaml.safe_load(file)
                    if not loaded_data:
                        raise IRValidatorException("YAML file is empty")
            except FileNotFoundError:
                raise IRValidatorException(f"YAML file not found: {yaml_file}")
            except yaml.YAMLError:
                raise IRValidatorException(f"Error parsing YAML file: {yaml_file}")

            missing_fields = required_fields - set(loaded_data.keys())
            if missing_fields:
                raise IRValidatorException(f"Missing required fields: {', '.join(missing_fields)}")

        return loaded_data

