def _get_conditionally_required_args(self, command_name: str, options_spec: List[Dictionary], args: Dictionary) -> List[str]:
    required_args = []
    for arg_name, spec in options_spec.items():
        if 'required_when' in spec:
            condition_command = spec['required_when'].get('command', None)
            condition_value = spec['required_when'].get('value', None)
            if command_name == condition_command and condition_value == args.get(arg_name, None):
